// Seitenliste 1..N bauen (alle Seiten bis Safety-Cap). max_pages kommt aus dem Dashboard.
const body = $('Webhook').first().json.body;
const CAP = 50;
const requested = body.max_pages != null ? parseInt(body.max_pages, 10) : null;
const maxPages = requested && requested > 0 ? Math.min(requested, CAP) : CAP;
const sellerId = body.seller_id;
const items = [];
for (let p = 1; p <= maxPages; p++) {
  items.push({ json: { page: p, seller_id: sellerId } });
}
return items;

function isbn10ToIsbn13(isbn10) {
  const clean = isbn10.replace(/[^0-9X]/gi, '').substring(0, 9);
  const withPrefix = '978' + clean;
  let sum = 0;
  for (let i = 0; i < 12; i++) {
    const digit = parseInt(withPrefix[i]);
    sum += i % 2 === 0 ? digit : digit * 3;
  }
  const check = (10 - (sum % 10)) % 10;
  return withPrefix + check;
}

// Heuristik: gebrauchte Angebote anhand expliziter Zustands-Labels erkennen (NICHT die
// "Neu & gebraucht ab"-Cross-Sell-Links). So bleibt Neuware erhalten, Gebrauchtware fliegt raus.
const USED_RE = /Gebraucht\s*[-\u2013\u2014]\s*(Wie neu|Sehr gut|Gut|Akzeptabel)|Zustand:\s*Gebraucht|gebraucht kaufen|used\s*[-\u2013\u2014]\s*(like new|very good|good|acceptable)/i;
const CAPTCHA_RE = /Enter the characters you see below|Geben Sie die Zeichen ein|api-services-support\.amazon\.com/i;

const pages = $input.all();
const products = [];
const seen = new Set();

for (const pageItem of pages) {
  const raw = pageItem.json.data ?? pageItem.json.body ?? pageItem.json;
  const htmlStr = typeof raw === 'string' ? raw : JSON.stringify(raw ?? '');
  if (!htmlStr || CAPTCHA_RE.test(htmlStr)) continue;

  const blockRegex = /data-asin="([A-Z0-9]{10})"([\s\S]*?)(?=data-asin="|$)/g;
  let match;
  while ((match = blockRegex.exec(htmlStr)) !== null) {
    const asin = match[1];
    const block = match[2];

    if (!/^\d{9}[\dX]$/.test(asin) && !/^\d{10}$/.test(asin)) continue;

    // Nur Neuware
    if (USED_RE.test(block)) continue;

    const isbn13 = isbn10ToIsbn13(asin);
    if (seen.has(isbn13)) continue;

    const titleMatch = block.match(/aria-label="([^"]{3,200})"/) ?? block.match(/<span[^>]*class="[^"]*a-size-medium[^"]*"[^>]*>([^<]{3,200})<\/span>/);
    const title = titleMatch ? titleMatch[1].trim() : null;

    const priceMatch = block.match(/(\d{1,3}[,.]\d{2})\s*\u20ac/) ?? block.match(/\u20ac\s*(\d{1,3}[,.]\d{2})/) ?? block.match(/"displayAmount":"EUR (\d{1,3}[,.]\d{2})"/i);
    let amazonPrice = null;
    if (priceMatch) amazonPrice = parseFloat(priceMatch[1].replace(',', '.'));

    if (isbn13 && amazonPrice != null) {
      seen.add(isbn13);
      products.push({ json: { asin, isbn13, title, amazon_price: amazonPrice, amazon_url: 'https://www.amazon.de/dp/' + asin } });
    }
  }
}

return products.length > 0 ? products : [{ json: { _noProducts: true } }];

const content = [];
for (const item of items) {
  const isbn = String(item.json.isbn13 ?? '').replace(/[-\s]/g, '').trim();
  if (/^\d{13}$/.test(isbn)) {
    content.push({ isbn });
  }
}
return [{ json: { content } }];

function normEAN(v) { return String(v ?? '').replace(/[^0-9X]/gi, ''); }
function parsePrice(v) {
  if (v == null) return null;
  if (typeof v === 'number') return v;
  const n = Number(String(v).replace(',', '.').trim());
  return Number.isFinite(n) ? n : null;
}
function getTypeCode(p) {
  const raw = p?.priceTypeDE ?? p?.priceTypeDe ?? p?.priceTypede ?? p?.priceType ?? p?.priceTypeD;
  return String(raw ?? '').trim().padStart(2, '0');
}

const vlbProducts = new Map();
for (const item of $('Collect VLB').all()) {
  const content = item.json?.content;
  if (Array.isArray(content)) {
    for (const p of content) {
      const ean = normEAN(p.gtin || p.isbn || p.identifier);
      const preis = parsePrice(p.priceEurD);
      const type = getTypeCode(p);
      const isBBP = ['04','24'].includes(type) || (p.priceFixedEurD === true && p.priceProvisionalEurD === false);
      if (ean && preis != null && isBBP) {
        vlbProducts.set(ean, { vlb_price: preis, title_vlb: p.title || p.shortTitle || null });
      }
    }
  }
}

const sellerAmazonId = $('Webhook').first().json.body?.seller_id ?? '';
const amazonItems = $('Parse Amazon HTML').all();

const now = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' });

const results = [];
for (const amazonItem of amazonItems) {
  const { isbn13, asin, title, amazon_price, amazon_url } = amazonItem.json;
  if (!isbn13 || amazon_price == null) continue;
  const vlbData = vlbProducts.get(isbn13);
  const vlb_price = vlbData?.vlb_price ?? null;
  // Buchpreisbindung: Verstoss = Verkauf UNTER dem VLB-Festpreis. OK = Festpreis oder darueber.
  const is_compliant = vlb_price != null ? amazon_price >= vlb_price : null;
  results.push({
    json: {
      'Datum': now,
      'Haendler': sellerAmazonId,
      'Buchtitel': title ?? vlbData?.title_vlb ?? '-',
      'Amazon_Preis_EUR': amazon_price,
      'VLB_BBP_Preis_EUR': vlb_price !== null ? vlb_price : '-',
      'ISBN13': isbn13,
      'ASIN': asin ?? '-',
      'Amazon_URL': amazon_url ?? ('https://www.amazon.de/dp/' + asin),
      'Status': is_compliant === true ? 'OK' : is_compliant === false ? 'VERSTOSS' : 'Kein VLB-Preis',
      '_is_compliant': is_compliant,
    }
  });
}

return results;

const webhookBody = $('Webhook').first().json.body;
const callbackUrl = webhookBody.callback_url;
const runId = webhookBody.run_id;
const sellerId = webhookBody.seller_id;

const allResults = $('Preisvergleich').all();
const totalItems = allResults.length;
let violations = 0;

const resultItems = allResults.map(r => {
  const d = r.json;
  if (d._is_compliant === false) violations++;
  return {
    isbn13: d['ISBN13'],
    asin: d['ASIN'],
    title: d['Buchtitel'],
    amazon_price: d['Amazon_Preis_EUR'],
    vlb_price: d['VLB_BBP_Preis_EUR'] === '-' ? null : d['VLB_BBP_Preis_EUR'],
    amazon_url: d['Amazon_URL'],
    status: d['Status'],
  };
});

// Proxy-Verbrauch aus den abgerufenen Amazon-Seiten messen (fuer Kostenanzeige im Dashboard)
let proxyBytes = 0;
let pagesScraped = 0;
for (const p of $('Amazon Pages').all()) {
  const raw = p.json.data ?? p.json.body ?? '';
  const s = typeof raw === 'string' ? raw : JSON.stringify(raw ?? '');
  proxyBytes += Buffer.byteLength(s, 'utf8');
  if (s && s.length > 100) pagesScraped++;
}

return [{
  json: {
    callback_url: callbackUrl,
    body: JSON.stringify({
      status: 'success',
      result_file_path: 'buchpreischeck/' + sellerId + '/' + runId + '.xlsx',
      metadata: { total_items: totalItems, violations_count: violations, proxy_bytes: proxyBytes, pages_scraped: pagesScraped, items: resultItems }
    })
  }
}];

const webhookBody = $('Webhook').first().json.body;
return [{
  json: {
    callback_url: webhookBody.callback_url,
    body: JSON.stringify({
      status: 'failed',
      error_message: 'Keine neuen Buecher auf dem Amazon-Schaufenster gefunden. Pruefe ob die Seller-ID korrekt ist, ob nur Gebrauchtware gelistet ist oder ob Amazon die Anfrage blockiert hat.'
    })
  }
}];
